const item = $input.first().json;

// 1. Extraer el body del webhook de manera segura
const input = item.body ? item.body : item;
const errores = [];

// 2. Validar campos obligatorios del mensaje individual de Discord
if (!input.message_id || String(input.message_id).trim() === '') {
  errores.push("El campo 'message_id' es obligatorio.");
}

if (!input.channel_id || String(input.channel_id).trim() === '') {
  errores.push("El campo 'channel_id' es obligatorio.");
}

if (!input.user_id || String(input.user_id).trim() === '') {
  errores.push("El campo 'user_id' es obligatorio.");
}

// Validar que el mensaje tenga texto real
if (!input.message || typeof input.message !== 'string' || input.message.trim() === '') {
  errores.push("El campo 'message' (texto) está vacío o no es válido.");
}

const esValido = errores.length === 0;

// 3. Devolver el resultado adaptado para el siguiente paso (ej. PostgreSQL)
return [{
  json: {
    es_valido: esValido,
    errores: errores,
    // Pasamos los datos limpios listos para la base de datos
    datos_mensaje: input 
  }
}];

