/**
 * NORMALIZADOR DE MENSAJE INDIVIDUAL - Simplificado
 */

const items = $input.all();
if (items.length === 0) return [];

const itemActual = items[0].json;
let data = itemActual.datos_mensaje || itemActual.payload_original || itemActual.body || itemActual;
if (data.body) data = data.body;

// Extraer los valores necesarios del mensaje de Python
const servidorNombre = data.server_name || "Servidor_G10";
const mensajeId = String(data.message_id || "");
const contenidoTexto = (data.message || "").trim();
const timestampOriginal = data.timestamp || new Date().toISOString();

const canalId = String(data.channel_id || "");
const canalNombre = data.channel_name ? `#${data.channel_name}` : "#general";

const autorId = String(data.user_id || "");
const autorNombre = data.display_name || data.username || "Anónimo";

// Retornar la estructura JSON limpia y simplificada
return [{
  json: {
    origen_comunidad: `Discord_${servidorNombre.replace(/\s+/g, '_')}`,
    identificador_origen: mensajeId,
    contenido: contenidoTexto,
    timestamp_origen: timestampOriginal,
    canal: {
      identificador_origen: canalId,
      nombre: canalNombre
    },
    autor: {
      identificador_origen: autorId,
      nombre: autorNombre
    }
  }
}];
